*/
scwin.init_conds = async function () {
    const binds = [{ id: "if_questComent", fn: function(){ return (!(String(((dma_ques.get("questComent") ?? (() => { throw new Error("unresolved:" + "ques.questComent"); })())) == null ? '' : ((dma_ques.get("questComent") ?? (() => { throw new Error("unresolved:" + "ques.questComent"); })()))).length === 0)); } }, { id: "c_when_42_txt", fn: function(){ return ((dma_ques.get("quesTpCd") ?? (() => { throw new Error("unresolved:" + "ques.quesTpCd"); })()) === '2'); } }, { id: "c_when_43_txt", fn: function(){ return ((dma_ques.get("quesTpCd") ?? (() => { throw new Error("unresolved:" + "ques.quesTpCd"); })()) === '3'); } }, { id: "c_when_44_txt", fn: function(){ return ((dma_ques.get("quesTpCd") ?? (() => { throw new Error("unresolved:" + "ques.quesTpCd"); })()) === '4'); } }, { id: "if_respnsMandtryNoContn_txt", fn: function(){ return (!(String(((dma_ques.get("respnsMandtryNoContn") ?? (() => { throw new Error("unresolved:" + "ques.respnsMandtryNoContn"); })())) == null ? '' : ((dma_ques.get("respnsMandtryNoContn") ?? (() => { throw new Error("unresolved:" + "ques.respnsMandtryNoContn"); })()))).length === 0)); } }, { id: "if_upQuesNo", fn: function(){ return ((dma_ques.get("upQuesNo") ?? (() => { throw new Error("unresolved:" + "ques.upQuesNo"); })()) !=='0'); } }, { id: "c_when_55", fn: function(){ return ((String((dma_ques.get("questAnsVal") ?? (() => { throw new Error("unresolved:" + "ques.questAnsVal"); })())).indexOf(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.candidateValSeq !== "undefined" && scwin.candidateValSeq !== null ? scwin.candidateValSeq : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "candidateValSeq" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("candidateValSeq"))) !== -1)); } }, { id: "c_otherwise_57", fn: function(){ return (!(((String((dma_ques.get("questAnsVal") ?? (() => { throw new Error("unresolved:" + "ques.questAnsVal"); })())).indexOf(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.candidateValSeq !== "undefined" && scwin.candidateValSeq !== null ? scwin.candidateValSeq : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "candidateValSeq" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("candidateValSeq"))) !== -1)))); } }, { id: "c_when_51", fn: function(){ return ((dma_ques.get("quesTpCd") ?? (() => { throw new Error("unresolved:" + "ques.quesTpCd"); })()) === '1'); } }, { id: "c_when_63", fn: function(){ return ((dma_ques.get("quesTpCd") ?? (() => { throw new Error("unresolved:" + "ques.quesTpCd"); })()) === '5'); } }, { id: "c_otherwise_67", fn: function(){ return (!(((dma_ques.get("quesTpCd") ?? (() => { throw new Error("unresolved:" + "ques.quesTpCd"); })()) === '1') || ((dma_ques.get("quesTpCd") ?? (() => { throw new Error("unresolved:" + "ques.quesTpCd"); })()) === '5'))); } }, { id: "c_when_72", fn: function(){ return ((String((dma_ques.get("questAnsVal") ?? (() => { throw new Error("unresolved:" + "ques.questAnsVal"); })())).indexOf(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.candidateValSeq !== "undefined" && scwin.candidateValSeq !== null ? scwin.candidateValSeq : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "candidateValSeq" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("candidateValSeq"))) !== -1)); } }, { id: "c_otherwise_74", fn: function(){ return (!(((String((dma_ques.get("questAnsVal") ?? (() => { throw new Error("unresolved:" + "ques.questAnsVal"); })())).indexOf(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.candidateValSeq !== "undefined" && scwin.candidateValSeq !== null ? scwin.candidateValSeq : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "candidateValSeq" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("candidateValSeq"))) !== -1)))); } }, { id: "btn_Prev", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "share" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("share")) != 0); } }, { id: "c_when_83", fn: function(){ return ((dma_status.get("last") ?? (() => { throw new Error("unresolved:" + "status.last"); })())); } }, { id: "c_otherwise_92", fn: function(){ return (!(((dma_status.get("last") ?? (() => { throw new Error("unresolved:" + "status.last"); })())))); } }, { id: "btn_Prev_2", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "share" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("share")) != 0); } }, { id: "if_modulus", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "modulus" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("modulus"))==9); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
/**
 * @method
 * @name scwin.init_fillGen
 * @author Inswave
 * @date 2026. 09. 29
 * @param boxId
 * @returns
 * @hidden N
*/
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_52", entity: "dlt_quesPollQuesCandidateVO", countIds: [], cells: [{ childId: "__rc8", fn: function (v, i) { return " (" + String(v("quesCandidateValSeq")) + ") " + String(v("quesCandidateVal")); } }] },
        { genId: "c_foreach_69", entity: "dlt_quesPollQuesCandidateVO", countIds: [], cells: [{ childId: "__rc9", fn: function (v, i) { return " (" + String(v("quesCandidateValSeq")) + ") " + String(v("quesCandidateVal")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getTotalRow();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb1", fn: function () { return String(dma_poll.get("questStrtDd")) + " ~ " + String(dma_poll.get("questEndDd")); } },
        { childId: "__rb3", fn: function () { return " " + String(dma_ques.get("quesNo")) + ". " + String(dma_ques.get("quesContn")); } },
        { childId: "__rb4", fn: function () { return "[택 " + String(dma_ques.get("ansChoicCnt")) + "개]"; } },
        { childId: "__rb5", fn: function () { return "[" + String(dma_ques.get("ansChoicCnt")) + "개까지 선택가능]"; } },
        { childId: "__rb6", fn: function () { return "(" + String(dma_ques.get("upQuesNo")) + "번 질문과 연관"; } },
        { childId: "__rb7", fn: function () { return "- 응답번호[" + String(dma_ques.get("respnsMandtryNoContn")) + "]시"; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

