*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.insQuest = undefined; try { scwin.insQuest = /* sdd-asis-lifecycle:begin insQuest — as-is 원문 본문(전환 이관 · 포팅 적용됨) */new Quest((String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "quesCnt" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("quesCnt"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "quesCnt" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("quesCnt")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "quesCnt" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("quesCnt"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "quesCnt" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("quesCnt"))))))/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil16200' }); }

scwin.Quest = Quest;

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        await scwin.init_rowCopy();
        await scwin.init_attrReals();
        await scwin.init_conds();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil16200.onpageload' });
    }
};


