    /* sdd-asis-lifecycle:begin fn_CheckForm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let isVallid = true;
    for (let i = 0; i < scwin.insQuest.quesObj.length; i++) {
        const insQues = scwin.insQuest.quesObj[i];
        const quesTpCd = insQues.quesTpCd;
        if (insQues.respnsMandtryYn === 'N') {
            switch (Number(quesTpCd)) {
                case 1:
                continue;
                case 2:
                var frm = (document.pollForm || { elements: [] });
                var ansVal = $c.util.getComponent('frm.' + 'ans' + insQues.quesNo).getValue();
                if (ansVal === '') {
                    continue;
                }
                break;
                case 3:
                var frm = (document.pollForm || { elements: [] });
                var ansVal = $c.util.getComponent('frm.' + 'ans' + insQues.quesNo).getValue();
                if (ansVal === '') {
                    continue;
                }
                break;
                case 4:
                continue;
                case 5:
                continue;
            }
        }
        switch (Number(quesTpCd)) {
            case 1:
            isVallid = await scwin.radioChk(insQues);
            break;
            case 2:
            isVallid = await scwin.checkboxChk1(insQues);
            break;
            case 3:
            isVallid = await scwin.checkboxChk2(insQues);
            break;
            case 4:
            isVallid = await scwin.checkboxChk3(insQues);
            break;
            case 5:
            isVallid = await scwin.textareaChk(insQues);
            break;
        }
        if (!isVallid) {
            break;
        }
    }
    return isVallid;
    /* sdd-asis-lifecycle:end */
};


