        case 1:
        var upAnsVal = scwin.getCheckedValue(upAnsObj);
        if (respnsMandtryNoContn === upAnsVal) {
            return true;
        } else {
            return false;
        }
        break;
        case 2:

        case 3:

        case 4:
        var upAnsVal = upAnsObj.value;
        if (scwin.ansContains(upAnsVal, respnsMandtryNoContn)) {
            return true;
        } else {
            return false;
        }
        break;
        case 5:
        var upAnsVal = upAnsObj.value;
        if (upAnsVal !== '') {
            return true;
        } else {
            return false;
        }
        break;
    }
    return false;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.ansContains
 * @author Inswave
 * @date 2026. 09. 29
 * @param _upAnsVal _respnsMandtryNoContn
 * @returns
 * @hidden N
*/
scwin.ansContains = function (_upAnsVal, _respnsMandtryNoContn) {
    /* sdd-asis-lifecycle:begin fn_AnsContains — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let isContains = false;
    if (_respnsMandtryNoContn !== '') {
        const respnsMandtryNoContn = _respnsMandtryNoContn.split(',');
        for (let i = 0; i < respnsMandtryNoContn.length; i++) {
            const resVal = respnsMandtryNoContn[i];
            if (_upAnsVal.indexOf(resVal) >= 0) {
                isContains = true;
                break;
            }
        }
    }
    return isContains;
    /* sdd-asis-lifecycle:end */
};


