/**
 * @method
 * @name scwin.chekRadioAns
 * @author Inswave
 * @date 2026. 09. 29
 * @param quesNo objparam2
 * @returns
 * @hidden N
*/
scwin.chekRadioAns = function (quesNo, objparam2) {
    /* sdd-asis-lifecycle:begin chekRadioAns — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const obj = document.getElementsByName(objparam2.name);
    for (let i = 0; i < obj.length; i++) {
        if (obj[i].checked) {
            const tmpAnsNo = i + 1;
            const strAnsNo = "0" + tmpAnsNo;
            for (let ii = 0; ii < scwin.insQuest.quesObj.length; ii++) {
                const insQues = scwin.insQuest.quesObj[ii];
                if (insQues.upQuesNo === quesNo) {
                    const relNo = "ans" + insQues.quesNo;
                    const relobj = document.getElementsByName(relNo);
                    if (insQues.respnsMandtryNoContn.indexOf(strAnsNo) > -1) {
                        for (var j = 0; j < relobj.length; j++) {
                            relobj[j].disabled = false;
                        }
                    } else {
                        for (var j = 0; j < relobj.length; j++) {
                            relobj[j].disabled = true;
                        }
                    }
                }
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.getMultiCheckedValue
 * @author Inswave
 * @date 2026. 09. 29
 * @param _obj
 * @returns
 * @hidden N
*/
scwin.getMultiCheckedValue = function (_obj) {
    /* sdd-asis-lifecycle:begin fn_GetMultiCheckedValue — as-is 원문 본문(전환 이관 · 포팅 적용됨) */

    let checkedValue = '';
    for(let i=0; i<_obj.length; i++){
        if(_obj[i].checked){
            if(checkedValue !== '') {
                checkedValue += ',';
            }
            checkedValue += _obj[i].value;
        }
    }
    return checkedValue;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fn_IsChecked
 * @author Inswave
 * @date 2026. 09. 29
 * @param _obj
 * @returns
 * @hidden N
*/
scwin.fn_IsChecked = function (_obj) {
    /* sdd-asis-lifecycle:begin fn_IsChecked — as-is 원문 본문(전환 이관 · 포팅 적용됨) */

    let isChecked = false;
    for(let i=0; i<_obj.length; i++){
        if(_obj[i].checked){
            isChecked = true;
            break;
        }
    }
    return isChecked;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.trim
 * @author Inswave
 * @date 2026. 09. 29
 * @param _str
 * @returns
 * @hidden N
*/
scwin.trim = function (_str) {
    /* sdd-asis-lifecycle:begin fn_Trim — as-is 원문 본문(전환 이관 · 포팅 적용됨) */

    if(typeof(_str)!=='undefined') return _str.replace(/^\s{1,}/, "").replace(/\s{1,}$/, "");
    else return _str;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.getCheckedValue
 * @author Inswave
 * @date 2026. 09. 29
 * @param _obj
 * @returns
 * @hidden N
*/
scwin.getCheckedValue = function (_obj) {
    /* sdd-asis-lifecycle:begin fn_GetCheckedValue — as-is 원문 본문(전환 이관 · 포팅 적용됨) */

    let checkedValue = '';
    for(let i=0; i<_obj.getItemCount(); i++){
        if(_obj[i].checked){
            checkedValue = _obj[i].value;
            break;
        }
    }
    return checkedValue;
    /* sdd-asis-lifecycle:end */
};
